import React, { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

export default function ProfDashboard() {
  const { user } = useAuth();
  const [reservations, setReservations] = useState([]);

  useEffect(() => {
    api.get('/api/reservations/mes-reservations').then(r => setReservations(r.data)).catch(() => {});
  }, []);

  async function updateReservation(id, statut) {
    await api.put(`/api/reservations/${id}`, { statut });
    setReservations(prev => prev.map(r => r.id === id ? { ...r, statut } : r));
  }

  const stats = [
    { icon: '📅', val: reservations.length, lbl: 'Réservations totales', color: '#6c63ff', bg: 'rgba(108,99,255,.1)' },
    { icon: '⏳', val: reservations.filter(r => r.statut === 'en_attente').length, lbl: 'En attente', color: '#f59e0b', bg: 'rgba(245,158,11,.1)' },
    { icon: '✅', val: reservations.filter(r => r.statut === 'confirmé').length, lbl: 'Confirmées', color: '#43e97b', bg: 'rgba(67,233,123,.1)' },
    { icon: '⭐', val: '4.8', lbl: 'Note moyenne', color: '#f59e0b', bg: 'rgba(245,158,11,.1)' },
  ];

  return (
    <div style={{ padding: 32 }}>
      <div style={{ marginBottom: 24 }}>
        <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.6rem', marginBottom: 4 }}>Bonjour, {user?.nom?.split(' ')[0]} 👨‍🏫</div>
        <div style={{ color: 'var(--text2)', fontSize: '.9rem' }}>Voici un aperçu de votre activité</div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 20, marginBottom: 28 }}>
        {stats.map(s => (
          <div key={s.lbl} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 20, display: 'flex', alignItems: 'center', gap: 16 }}>
            <div style={{ width: 48, height: 48, borderRadius: 12, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.4rem' }}>{s.icon}</div>
            <div>
              <div style={{ fontFamily: 'Syne', fontSize: '1.7rem', fontWeight: 800, color: s.color }}>{s.val}</div>
              <div style={{ fontSize: '.8rem', color: 'var(--text2)' }}>{s.lbl}</div>
            </div>
          </div>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 24 }}>
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24 }}>
          <div style={{ fontWeight: 600, marginBottom: 16 }}>📩 Demandes de réservation</div>
          {reservations.length === 0 && <div style={{ textAlign: 'center', padding: 24, color: 'var(--text2)', fontSize: '.85rem' }}>Aucune réservation.</div>}
          {reservations.map(r => (
            <div key={r.id} style={{ background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, padding: 14, marginBottom: 10 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <div style={{ fontWeight: 600, fontSize: '.88rem' }}>Réservation #{r.id}</div>
                  <div style={{ fontSize: '.78rem', color: 'var(--text2)' }}>📅 {r.date_cours} · {String(r.heure_debut || '').slice(0, 5)}</div>
                </div>
                {r.statut === 'en_attente' ? (
                  <div style={{ display: 'flex', gap: 6 }}>
                    <button onClick={() => updateReservation(r.id, 'confirmé')} style={{ padding: '5px 10px', background: 'rgba(67,233,123,.15)', color: '#43e97b', border: '1px solid rgba(67,233,123,.3)', borderRadius: 7, cursor: 'pointer', fontSize: '.8rem', fontWeight: 600 }}>✅ Accepter</button>
                    <button onClick={() => updateReservation(r.id, 'refusé')} style={{ padding: '5px 10px', background: 'rgba(255,101,132,.15)', color: '#ff6584', border: '1px solid rgba(255,101,132,.3)', borderRadius: 7, cursor: 'pointer', fontSize: '.8rem', fontWeight: 600 }}>❌ Refuser</button>
                  </div>
                ) : (
                  <span style={{ background: r.statut === 'confirmé' ? 'rgba(67,233,123,.15)' : 'rgba(255,101,132,.15)', color: r.statut === 'confirmé' ? '#43e97b' : '#ff6584', fontSize: '.72rem', fontWeight: 600, padding: '2px 8px', borderRadius: 20 }}>{r.statut}</span>
                )}
              </div>
            </div>
          ))}
        </div>

        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24 }}>
          <div style={{ fontWeight: 600, marginBottom: 16 }}>🗓 Mes disponibilités</div>
          {['Lundi 14h–16h', 'Mardi 09h–11h', 'Mercredi 15h–17h', 'Vendredi 10h–12h'].map(c => (
            <div key={c} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 12px', background: 'rgba(67,233,123,.08)', border: '1px solid rgba(67,233,123,.2)', borderRadius: 8, marginBottom: 8 }}>
              <span style={{ fontSize: '.85rem', color: '#43e97b' }}>{c}</span>
              <button style={{ padding: '4px 8px', background: 'rgba(255,101,132,.1)', color: '#ff6584', border: '1px solid rgba(255,101,132,.2)', borderRadius: 6, cursor: 'pointer', fontSize: '.75rem' }}>🗑</button>
            </div>
          ))}
          <button style={{ width: '100%', marginTop: 8, padding: '9px', background: 'rgba(67,233,123,.1)', color: '#43e97b', border: '1px solid rgba(67,233,123,.3)', borderRadius: 8, cursor: 'pointer', fontWeight: 600, fontSize: '.85rem' }}>+ Ajouter un créneau</button>
        </div>
      </div>
    </div>
  );
}
